<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();
try{$db=database();$total=(int)$db->query('SELECT COUNT(*) FROM students')->fetchColumn();$users=(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn();$activeUsers=(int)$db->query("SELECT COUNT(*) FROM users WHERE status='Active'")->fetchColumn();$active=(int)$db->query("SELECT COUNT(*) FROM students WHERE status='Active'")->fetchColumn();$recentCount=(int)$db->query('SELECT COUNT(*) FROM students WHERE created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)')->fetchColumn();$q=$db->query('SELECT * FROM students ORDER BY created_at DESC,id DESC LIMIT 8');$recent=array_map('sms_student_for_dashboard',$q->fetchAll());json_response(['ok'=>true,'stats'=>['students'=>$total,'users'=>$users,'active_users'=>$activeUsers,'active_students'=>$active,'recent_registrations'=>$recentCount],'recent'=>$recent]);}
catch(PDOException $e){error_log('EduCore dashboard API: '.$e->getMessage());json_response(['ok'=>false,'error'=>'Dashboard data is temporarily unavailable.'],503);}
function sms_student_for_dashboard(array $r):array{$id=$r['id'];$r['id']='s'.$id;$r['regNo']=$r['registration_number'];$r['name']=$r['full_name'];$r['dob']=$r['date_of_birth'];$r['joined']=$r['created_at'];$r['initials']=implode('',array_map(fn($p)=>substr($p,0,1),array_slice(preg_split('/\s+/',trim($r['full_name'])),0,2)));unset($r['registration_number'],$r['full_name'],$r['date_of_birth']);return $r;}
